#!/bin/bash
# Task 091 -- meshsim v1.25 section 8e verification (WORKER11): branch s8 at 7ca2110 (section 8: misalignment, the replayer's
# bad write, reserved digits and modes, runs past the table's end and the "ignored" misuses as undefined-behavior stops;
# the gather unit's 128-bit copies; the 256-byte ROM). run_tests.sh's quick suite (tools/run_quick.sh, 8 at a time) and
# its full-mode extras (tools/run_full.sh, 4 at a time). No p4: task 089 measured it (1,229,008 cycles) and 8e doesn't
# touch the sort. The kit (wip/ at Java 17 with every image prebuilt) is embedded below, SHA-256 checked. The whole
# quick suite passed locally (34 steps). Expected ~10 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/091-w11-s8e-verify; mkdir -p "$RES"
WANT=6e432423c75fa5192ac22a97aefc361651efbf807be8d4473c4b4c2707dedc24
W=/tmp/w11-091; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/wip/meshsim" || exit 2
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
echo "run_quick.sh exit $RQ, run_full.sh exit $RF at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ]; exit $?
